-- Ledger core (design §3) plus API bookkeeping (§5, §10).
--
-- IDs are UUIDv7 generated by the server. Amounts and quantities are
-- unconstrained NUMERIC, so any exact value is stored as-is; per-commodity
-- precision is enforced by the domain crate. No column is ever floating point
-- (checked by a test). Enumerations are text with CHECK constraints.
--
-- CHECK constraints repeat the ledger invariants that need no lookups, as a
-- second line of defense behind `domain`.

CREATE TABLE commodity (
    id        uuid PRIMARY KEY,
    code      text NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9.-]{1,16}$'),
    kind      text NOT NULL CHECK (kind IN ('fiat', 'security', 'fund', 'crypto', 'other')),
    precision smallint NOT NULL CHECK (precision BETWEEN 0 AND 18)
);

CREATE TABLE party (
    id   uuid PRIMARY KEY,
    name text NOT NULL UNIQUE CHECK (name <> ''),
    kind text NOT NULL CHECK (kind IN ('household', 'person', 'business'))
);
-- Exactly one household per server (at most one here; the API creates it).
CREATE UNIQUE INDEX party_one_household ON party (kind) WHERE kind = 'household';

CREATE TABLE account (
    id       uuid PRIMARY KEY,
    name     text NOT NULL UNIQUE CHECK (name <> ''),
    kind     text NOT NULL CHECK (kind IN
                 ('checking', 'savings', 'credit_card', 'brokerage', 'mortgage', 'cash', 'other')),
    owner_id uuid NOT NULL REFERENCES party,
    liquid   boolean NOT NULL
);

CREATE TABLE counterparty (
    id     uuid PRIMARY KEY,
    name   text NOT NULL UNIQUE CHECK (name <> ''),
    system text UNIQUE CHECK (system IN ('opening_balances', 'reconciliation'))
);
INSERT INTO counterparty (id, name, system) VALUES
    (gen_random_uuid(), 'Opening balances', 'opening_balances'),
    (gen_random_uuid(), 'Reconciliation', 'reconciliation');

CREATE TABLE category (
    id   uuid PRIMARY KEY,
    name text NOT NULL UNIQUE CHECK (name <> '')
);

CREATE TABLE tag (
    id   uuid PRIMARY KEY,
    name text NOT NULL UNIQUE CHECK (name <> '')
);

CREATE TABLE transaction (
    id          uuid PRIMARY KEY,
    date        date NOT NULL,
    description text NOT NULL,
    notes       text,
    -- Bumped on every edit; the API's ETag.
    version     bigint NOT NULL DEFAULT 1,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX transaction_date ON transaction (date);

CREATE TABLE transaction_tag (
    transaction_id uuid NOT NULL REFERENCES transaction ON DELETE CASCADE,
    tag_id         uuid NOT NULL REFERENCES tag,
    PRIMARY KEY (transaction_id, tag_id)
);

CREATE TABLE split (
    transaction_id       uuid NOT NULL REFERENCES transaction ON DELETE CASCADE,
    position             smallint NOT NULL CHECK (position >= 0),
    from_account_id      uuid REFERENCES account,
    from_counterparty_id uuid REFERENCES counterparty,
    from_commodity_id    uuid NOT NULL REFERENCES commodity,
    from_quantity        numeric NOT NULL CHECK (from_quantity > 0),
    to_account_id        uuid REFERENCES account,
    to_counterparty_id   uuid REFERENCES counterparty,
    to_commodity_id      uuid NOT NULL REFERENCES commodity,
    to_quantity          numeric NOT NULL CHECK (to_quantity > 0),
    purpose_id           uuid REFERENCES party,
    category_id          uuid REFERENCES category,
    description          text,
    PRIMARY KEY (transaction_id, position),

    -- Each leg is an account or a counterparty, never both.
    CHECK (num_nonnulls(from_account_id, from_counterparty_id) = 1),
    CHECK (num_nonnulls(to_account_id, to_counterparty_id) = 1),
    -- At least one side is yours.
    CHECK (from_account_id IS NOT NULL OR to_account_id IS NOT NULL),
    -- Same commodity: same quantity.
    CHECK (from_commodity_id <> to_commodity_id OR from_quantity = to_quantity),
    -- No moving a commodity from an account into itself.
    CHECK (from_account_id IS DISTINCT FROM to_account_id
           OR from_commodity_id <> to_commodity_id)
);
CREATE INDEX split_from_account ON split (from_account_id) WHERE from_account_id IS NOT NULL;
CREATE INDEX split_to_account ON split (to_account_id) WHERE to_account_id IS NOT NULL;
CREATE INDEX split_from_counterparty ON split (from_counterparty_id)
    WHERE from_counterparty_id IS NOT NULL;
CREATE INDEX split_to_counterparty ON split (to_counterparty_id)
    WHERE to_counterparty_id IS NOT NULL;
CREATE INDEX split_category ON split (category_id) WHERE category_id IS NOT NULL;
CREATE INDEX split_purpose ON split (purpose_id) WHERE purpose_id IS NOT NULL;

-- Bearer tokens (§10 tier 1). Only a hash of the secret is stored.
CREATE TABLE api_token (
    id          uuid PRIMARY KEY,
    name        text NOT NULL UNIQUE CHECK (name <> ''),
    secret_hash text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    revoked_at  timestamptz
);

-- Who changed what (§3.1). Rows are only ever inserted.
CREATE TABLE audit_log (
    id        uuid PRIMARY KEY,
    at        timestamptz NOT NULL DEFAULT now(),
    token_id  uuid REFERENCES api_token,
    action    text NOT NULL CHECK (action IN ('create', 'update', 'delete')),
    entity    text NOT NULL,
    entity_id uuid NOT NULL,
    before    jsonb,
    after     jsonb
);
CREATE INDEX audit_log_entity ON audit_log (entity, entity_id);

-- Idempotency keys for POSTs (§5): a retried request gets the stored response.
CREATE TABLE idempotency_key (
    token_id        uuid NOT NULL REFERENCES api_token,
    key             text NOT NULL,
    request_hash    text NOT NULL,
    response_status smallint NOT NULL,
    response_body   jsonb NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (token_id, key)
);
